    void targetSlotUniqueCommitKeeps4514AndRollbackStillAddsOneDefaultRow(boolean rollback)throws Exception{var before=facts();var expected=new AtomicReference<Map<String,List<Map<String,Object>>>>();var pool=Executors.newSingleThreadExecutor();var pending=new ArrayList<Future<Outcome>>();var lower=new AtomicReference<Instant>();int seq=nextSeq();try{tx().executeWithoutResult(t->{expected.set(winner(before,secondOrder,"BOOKED"));int holder=jdbc.queryForObject("select pg_backend_pid()",Integer.class);lower.set(pgClock());pending.add(pool.submit(this::book));waitForHolder(holder,pending.getFirst(),"target-unique:"+(rollback?"rollback":"commit"));if(rollback)t.setRollbackOnly();});var response=finish(pending.getFirst());if(rollback)accepted(response,before,seq,lower.get());else refused(response,200,4514,expected.get());}finally{close(pool);}}
